// src/lib/recorded.ts
var ASK_MAX = 300;
function cleanAsk(raw) {
  if (raw == null) return null;
  if (typeof raw !== "string") return void 0;
  const text = raw.replace(/[\u0000-\u001f\u007f]+/g, " ").replace(/\s+/g, " ").trim();
  if (!text) return null;
  if (text.length < 3 || text.length > ASK_MAX) return void 0;
  return text;
}
function analysisKey(s, ask) {
  return ask ? `${scenarioKey(s)}|ask:${ask.toLowerCase()}` : scenarioKey(s);
}
function scenarioKey(s) {
  return JSON.stringify([
    s.environment,
    s.question,
    s.oxygenPct,
    s.pressurePsi,
    s.gravityG,
    s.airflowMs,
    s.fuel,
    s.material,
    s.thicknessMm,
    s.flowDirection,
    s.includeAdjacent
  ]);
}

