// src/lib/cells.ts
function cellValues(raw, parser = "parseCell") {
  const text = String(raw ?? "").trim();
  if (!text) return [];
  if (parser === "pctO2InText") return [...text.matchAll(/(\d+(?:\.\d+)?)\s*%\s*O2/gi)].map((m) => Number(m[1]));
  const parts = text.replace(/~/g, "").split(/;|\bor\b|,|\bto\b|(?<=\d)\s+-\s+(?=\d)/).map((s) => s.trim()).filter(Boolean);
  const out = [];
  for (const p of parts) {
    const m = /^(\d*\.?\d+)\s*(atm|bar|mmhg|cm\/s|%|mm|cm)?$/i.exec(p);
    if (!m) return [];
    out.push(Number(m[1]));
  }
  return out;
}

// server/rows.ts
var PROFILES = normalized_conditions_default.profiles;
function table(id) {
  const t = TABLES[id];
  if (!t) throw new Error(`Run table ${id} is not indexed; run npm run data:normalize`);
  return t;
}
function rowText(header, cells, cap = 420) {
  const parts = header.map((h, i) => [h.replace(/\s+/g, " ").trim().replace(/^\?-g/, "\xB5-g (written ?-g in the NASA file)"), (cells[i] ?? "").replace(/\s+/g, " ").trim()]).filter(([h, v]) => h && v).map(([h, v]) => `${h}: ${v}`);
  const text = parts.join("; ");
  return text.length > cap ? text.slice(0, cap).replace(/;[^;]*$/, "") + "; \u2026" : text;
}
function nearestRows(profileId, name, scenario, k = 3) {
  const p = PROFILES[profileId];
  if (!p) return [];
  const t = table(p.table);
  const keys = Object.keys(p.conditions).filter((key) => scenario[key] != null);
  const cols = keys.map((key) => {
    const c = p.conditions[key];
    return { key, c, i: t.header.findIndex((h) => h.trim() === c.column), span: Math.max(c.max - c.min, 1e-6) };
  }).filter((x) => x.i >= 0);
  const scored = t.rows.map((r) => {
    let d = 0, n = 0;
    for (const { key, c, i, span } of cols) {
      const vals = cellValues(r.cells[i], c.parser).map((v) => v * c.factor);
      if (!vals.length) continue;
      d += Math.min(...vals.map((v) => Math.abs(v - scenario[key]))) / span;
      n++;
    }
    return { r, d: n ? d / n : Infinity, n };
  }).filter((x) => x.n > 0 || !cols.length).sort((a, b) => a.d - b.d || a.r.sourceRow - b.r.sourceRow).slice(0, k);
  return scored.map(({ r }) => ({
    id: `${profileId}:row${r.sourceRow}`,
    label: `${name} \xB7 NASA ${p.table} row ${r.sourceRow}`,
    origin: "nasa",
    text: rowText(t.header, r.cells)
  }));
}

